import{_ as p,a0 as u,w as o,s as m,I as l,x as t,a1 as n,A as s,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"MX Linux：一款專注於簡潔性的中等體量發行版 | LCTT x X-CMD","titleTemplate":false,"description":"MX Linux：一款專注於簡潔性的中等體量發行版 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"MX Linux：一款專注於簡潔性的中等體量發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"MX Linux：一款專注於簡潔性的中等體量發行版 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20180406 MX Linux- A Mid-Weight Distro Focused on Simplicity","title":"MX Linux：一款專注於簡潔性的中等體量發行版","tag":"201907","desc":""},"relativePath":"201907/20180406 MX Linux- A Mid-Weight Distro Focused on Simplicity.md","filePath":"[post].md"}'),r={name:"201907/20180406 MX Linux- A Mid-Weight Distro Focused on Simplicity.md"};function x(d,i,f,L,w,X){const e=u("Link");return o(),m("div",null,[i[26]||(i[26]=l("h1",{id:"mx-linux-一款專注於簡潔性的中等體量發行版",tabindex:"-1"},[t("MX Linux：一款專注於簡潔性的中等體量發行版 "),l("a",{class:"header-anchor",href:"#mx-linux-一款專注於簡潔性的中等體量發行版","aria-label":"Permalink to “MX Linux：一款專注於簡潔性的中等體量發行版”"},"​")],-1)),i[27]||(i[27]=l("blockquote",null,[l("p",null,"這個發行版可以使任何人在 Linux 上如家一般。")],-1)),i[28]||(i[28]=l("p",null,[l("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/mxlinux.png?itok=OLjmCxT9",alt:""})],-1)),l("p",null,[i[2]||(i[2]=t("Linux 有着如此多種的發行版。許多發行版為了使自己與眾不同而做出了很多改變。另一方面，許多發行版之間的區別又是如此之小，你可能會問為什麼有人還願意不厭其煩的重複別人已經做過的工作呢？也正是基於這一疑惑，讓我好奇為什麼 ",-1)),n(e,{href:"https://antixlinux.com/"},{default:s(()=>[...i[0]||(i[0]=[t("antiX",-1)])]),_:1}),i[3]||(i[3]=t(" 和 ",-1)),n(e,{href:"https://en.wikipedia.org/wiki/MEPIS"},{default:s(()=>[...i[1]||(i[1]=[t("MEPIS",-1)])]),_:1}),i[4]||(i[4]=t("這兩個社區要聯合推出一個特殊的發行版，考慮到具體情況應該會是一個搭載 Xfce 桌面並基於 antiX 的版本，由 MEPIS 社區承擔開發。",-1))]),l("p",null,[i[6]||(i[6]=t("這一開發中的使用 Xfce 桌面的 antiX 系統是否會基於它之前的發行版呢？畢竟，antiX 旨在提供一個“基於 Debian 穩定版的快速、輕量級、易於安裝的非 systemd 的 live CD 發行版”。antiX 所搭載的桌面是 ",-1)),n(e,{href:"https://lxde.org/"},{default:s(()=>[...i[5]||(i[5]=[t("LXDE",-1)])]),_:1}),i[7]||(i[7]=t("，能夠極好的滿足關於輕量化系統的相關要求和特性。那究竟是什麼原因使得 antiX 決定構建另一個輕量化發行版呢，僅僅是因為這次換成了 Xfce 嗎？好吧，Linux 社區中的任何人都知道，增加了不同風格的好的輕量級發行版是值得一試的（特別是可以使得我們的舊硬件擺脱進入垃圾填埋場的宿命）。當然，LXDE 和 Xfce 並不完全屬於同一類別。LXDE 應該被認為是一個真正的輕量級桌面，而 Xfce 應該被認為是一箇中等體量的桌面。朋友們，這就是為什麼 MX Linux 是 antiX 的一個重要迭代的關鍵。一個基於 Debian 的中等體量的發行版，它包含你完成工作所需的所有工具。",-1))]),i[29]||(i[29]=l("p",null,"但是在 MX Linux 中有一些直接從 antiX 借用來的非常有用的東西 —— 那就是安裝工具。當我初次設置了 VirtualBox 虛擬機來安裝 MX Linux 時，我認為安裝的系統將是我已經習慣的典型的、非常簡單的 Linux 系統。令我非常驚訝的是，MX Linux 使用的 antiX 安裝程序打破了以往的痛點，特別是對於那些對嘗試 Linux 持觀望態度的人來説。",-1)),i[30]||(i[30]=l("p",null,"因此，甚至在我開始嘗試 MX Linux 之前，我就對它有了深刻的印象。讓我們來看看是什麼讓這個發行版的安裝如此特別，最後再來看看桌面。",-1)),l("p",null,[i[9]||(i[9]=t("你可以從",-1)),n(e,{href:"https://mxlinux.org/download-links"},{default:s(()=>[...i[8]||(i[8]=[t("這裏",-1)])]),_:1}),i[10]||(i[10]=t("下載 MX Linux 17.1。系統的最低要求是:",-1))]),i[31]||(i[31]=a('<ul><li>CD/DVD驅動器（以及能夠從該驅動器引導的 BIOS）或 live USB（以及能夠從 USB 引導的 BIOS）</li><li>英特爾 i486 或 AMD 處理器</li><li>512 MB 內存</li><li>5 GB 硬盤空間</li><li>揚聲器，AC97 或 HDA-compatible 聲卡</li><li>作為一個 LiveUSB 使用，需要 4 GB 空間</li></ul><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>MX Linux 安裝程序使安裝 Linux 變得輕而易舉。雖然它可能不是外觀最現代化的安裝工具，但也已經差不多了。安裝的要點是從選擇磁盤和選擇安裝類型開始的（圖 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/mxlinux_1.jpg?itok=i9bNScjH" alt="install" title="install"></p><p><em>圖 1：MX Linux 的安裝程序截圖之一</em></p><p>下一個重要的界面（圖 2）要求你設置一個計算機名稱、域名和（如果需要的話，為微軟網絡設置）工作組。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/mxlinux_2.jpg?itok=72nWxkGo" alt="network"></p><p><em>圖 2：設置網絡名稱</em></p><p>配置工作組的能力是第一個真正值得稱讚的。這是我記憶中第一款在安裝期間提供此選項的發行版。它還應該提示你，MX Linux 提供了開箱即用的共享目錄功能。它做到了，而且深藏功與名。它並不完美，但它可以在不需要安裝任何額外包的情況下工作（稍後將詳細介紹）。</p><p>最後一個重要的安裝界面（需要用户交互）是創建用户帳户和 root 權限的密碼（圖 3）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/mxlinux_3.jpg?itok=ppf2l_bm" alt="user" title="user"></p><p><em>圖 3：設置用户帳户詳細信息和 root 用户密碼</em></p><p>最後一個界面設置完成後，安裝將完成並要求重新啓動。重啓後，你將看到登錄屏幕。登錄並享受 MX Linux 帶來的體驗。</p><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>Xfce 桌面是一個非常容易上手的界面。默認設置將面板位於屏幕的左邊緣（圖 4）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/mxlinux_4.jpg?itok=mS1eBy9m" alt="desktop" title="desktop"></p><p><em>圖 4：MX Linux 的默認桌面</em></p><p>如果你想將面板移動到更傳統的位置，右鍵單擊面板上的空白點，然後單擊“面板”&gt;“面板首選項”。在顯示的窗口中（圖 5），單擊樣式下拉菜單，在桌面欄、垂直欄或水平欄之間進行選擇你想要的模式。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/mxlinux_5.jpg?itok=wsN1hviN" alt="panel" title="panel"></p><p><em>圖 5：配置 MX Linux 面板</em></p><p>桌面欄和垂直選項的區別在於，在桌面欄模式下，面板垂直對齊，就像在垂直模式下一樣，但是插件是水平放置的。這意味着你可以創建更寬的面板（用於寬屏佈局）。如果選擇水平佈局，它將默在頂部，然後你必須取消鎖定面板，單擊關閉，然後（使用面板左側邊緣的拖動手柄）將其拖動到底部。你可以回到面板設置窗口並重新鎖定面板。</p><p>除此之外，使用 Xfce 桌面對於任何級別的用户來説都是無需動腦筋的事情……就是這麼簡單。你會發現很多涵蓋了生產力（LibreOffice、Orage Calendar、PDF-Shuffler）、圖像（GIMP)、通信（Firefox、Thunderbird、HexChat）、多媒體（Clementine、guvcview SMTube、VLC媒體播放器）的軟件，和一些 MX Linux 專屬的工具（稱為 MX 工具，涵蓋了 live-USB 驅動器製作工具、網絡助手、包管理工具、倉庫管理工具、live ISO 快照工具等等）。</p><h3 id="samba" tabindex="-1">Samba <a class="header-anchor" href="#samba" aria-label="Permalink to “Samba”">​</a></h3><p>讓我們討論一下如何將文件夾共享到你的網絡。正如我所提到的，你不需要安裝任何額外的包就可以使其正常工作。只需打開文件管理器，右鍵單擊任何位置，並選擇網絡上的共享文件夾。系統將提示你輸入管理密碼（已在安裝期間設置）。驗證成功之後，Samba 服務器配置工具將打開（圖 6）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/mxlinux_6.jpg?itok=vw8mIp9T" alt="sharing" title="sharing"></p><p><em>圖 6：向網絡共享一個目錄</em></p><p>單擊“+”按鈕配置你的共享。你將被要求指定一個目錄，為共享提供一個名稱/描述，然後決定該共享是否可寫和可見（圖 7）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/mxlinux_7.jpg?itok=tRIWdcEk" alt="sharing" title="sharing"></p><p><em>圖 7：在 MX Linux 上配置共享</em></p><p>當你單擊 Access 選項時，你可以選擇是讓每個人都訪問共享，還是限於特定的用户。問題就出在這裏。此時，沒有用户可以共享。為什麼？因為它們還沒有被添加。有兩種方法可以把它們添加到共享：從命令列或使用我們已經打開的工具。讓我們用一種更為簡單的方法。在 Samba 服務器配置工具的主窗口中，單擊“首選項” &gt; “Samba 用户”。在彈出的窗口中，單擊“添加用户”。</p><p>將出現一個新窗口（圖 8），你需要從下拉框中選擇用户，輸入 Windows 用户名，併為用户鍵入/重新鍵入密碼。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/floated_images/public/mxlinux_8.jpg?itok=ZS6lhZN2" alt="Samba" title="Samba"></p><p><em>圖 8：向 Samba 添加用户</em></p><p>一旦你單擊“確定”，這用户就會被添加，並且基於你的網絡的對用户的共享功能也隨之啓用。創建 Samba 共享從未變得如此容易。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>MX Linux 使任何從桌面操作系統轉到 Linux 都變得非常簡單。儘管有些人可能會覺得桌面界面不太現代，但發行版的主要關注點不是美觀，而是簡潔。為此，MX Linux 以出色的方式取得了成功。Linux 的這個特色發行版可以讓任何人在使用 Linux 的過程中感到賓至如歸。嘗試這一中等體量的發行版，看看它能否作為你的日常系統。</p><hr>',37)),l("p",null,[i[12]||(i[12]=t("via: ",-1)),n(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/4/mx-linux-mid-weight-distro-focused-simplicity"},{default:s(()=>[...i[11]||(i[11]=[t("https://www.linux.com/learn/intro-to-linux/2018/4/mx-linux-mid-weight-distro-focused-simplicity",-1)])]),_:1})]),l("p",null,[i[17]||(i[17]=t("作者：",-1)),n(e,{href:"https://www.linux.com/users/jlwallen"},{default:s(()=>[...i[13]||(i[13]=[t("JACK WALLEN",-1)])]),_:1}),i[18]||(i[18]=t(" 譯者：",-1)),n(e,{href:"https://github.com/qfzy1233"},{default:s(()=>[...i[14]||(i[14]=[t("qfzy1233",-1)])]),_:1}),i[19]||(i[19]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...i[15]||(i[15]=[t("wxy",-1)])]),_:1}),i[20]||(i[20]=t(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...i[16]||(i[16]=[t("lujun9972",-1)])]),_:1})]),l("p",null,[i[23]||(i[23]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...i[21]||(i[21]=[t("LCTT",-1)])]),_:1}),i[24]||(i[24]=t(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:s(()=>[...i[22]||(i[22]=[t("Linux中國",-1)])]),_:1}),i[25]||(i[25]=t(" 榮譽推出",-1))])])}const S=p(r,[["render",x]]);export{M as __pageData,S as default};
